CREATE DATABASE IF NOT EXISTS phone_source CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE phone_source;
CREATE TABLE IF NOT EXISTS thuong_hieu (ma_thuong_hieu VARCHAR(20) PRIMARY KEY, ten_thuong_hieu VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS san_pham (ma_san_pham VARCHAR(20) PRIMARY KEY, ten_san_pham VARCHAR(120) NOT NULL, ma_thuong_hieu VARCHAR(20) NOT NULL, FOREIGN KEY(ma_thuong_hieu) REFERENCES thuong_hieu(ma_thuong_hieu)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS phien_ban_san_pham (ma_sku VARCHAR(30) PRIMARY KEY, ma_san_pham VARCHAR(20) NOT NULL, ram_gb INT NOT NULL CHECK(ram_gb>0), bo_nho_gb INT NOT NULL CHECK(bo_nho_gb>0), mau_sac VARCHAR(30) NOT NULL, FOREIGN KEY(ma_san_pham) REFERENCES san_pham(ma_san_pham)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tinh_thanh (ma_tinh VARCHAR(10) PRIMARY KEY, ten_tinh VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cua_hang (ma_cua_hang VARCHAR(20) PRIMARY KEY, ten_cua_hang VARCHAR(100) NOT NULL, ma_tinh VARCHAR(10) NOT NULL, FOREIGN KEY(ma_tinh) REFERENCES tinh_thanh(ma_tinh)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS khach_hang (ma_khach_hang VARCHAR(20) PRIMARY KEY, ho_ten VARCHAR(100) NOT NULL, ma_tinh VARCHAR(10) NOT NULL, FOREIGN KEY(ma_tinh) REFERENCES tinh_thanh(ma_tinh)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kenh_ban (ma_kenh VARCHAR(20) PRIMARY KEY, ten_kenh VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS khuyen_mai (ma_khuyen_mai VARCHAR(20) PRIMARY KEY, ten_khuyen_mai VARCHAR(100) NOT NULL, ngay_bat_dau DATE NOT NULL, ngay_ket_thuc DATE NOT NULL, CHECK(ngay_bat_dau<=ngay_ket_thuc)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS nhan_vien (ma_nhan_vien VARCHAR(20) PRIMARY KEY, ho_ten VARCHAR(100) NOT NULL, ma_cua_hang VARCHAR(20) NOT NULL, FOREIGN KEY(ma_cua_hang) REFERENCES cua_hang(ma_cua_hang)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS don_hang (ma_don_hang VARCHAR(25) PRIMARY KEY, ngay_dat DATE NOT NULL, ma_nhan_vien VARCHAR(20) NOT NULL, FOREIGN KEY(ma_nhan_vien) REFERENCES nhan_vien(ma_nhan_vien), INDEX ix_ngay_dat(ngay_dat), ma_cua_hang VARCHAR(20) NOT NULL, ma_khach_hang VARCHAR(20) NOT NULL, ma_kenh VARCHAR(20) NOT NULL, trang_thai VARCHAR(20) NOT NULL CHECK(trang_thai IN ('COMPLETED','PARTIALLY_RETURNED','RETURNED','CANCELLED')), FOREIGN KEY(ma_cua_hang) REFERENCES cua_hang(ma_cua_hang), FOREIGN KEY(ma_khach_hang) REFERENCES khach_hang(ma_khach_hang), FOREIGN KEY(ma_kenh) REFERENCES kenh_ban(ma_kenh)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chi_tiet_don_hang (ma_chi_tiet VARCHAR(30) PRIMARY KEY, ma_don_hang VARCHAR(25) NOT NULL, ma_sku VARCHAR(30) NOT NULL, ma_khuyen_mai VARCHAR(20) NOT NULL, so_luong INT NOT NULL CHECK(so_luong>0), don_gia DECIMAL(18,2) NOT NULL CHECK(don_gia>=0), giam_gia DECIMAL(18,2) NOT NULL CHECK(giam_gia>=0 AND giam_gia<=so_luong*don_gia), gia_von DECIMAL(18,2) NOT NULL CHECK(gia_von>=0), FOREIGN KEY(ma_don_hang) REFERENCES don_hang(ma_don_hang), FOREIGN KEY(ma_sku) REFERENCES phien_ban_san_pham(ma_sku), FOREIGN KEY(ma_khuyen_mai) REFERENCES khuyen_mai(ma_khuyen_mai)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tra_hang (ma_tra_hang VARCHAR(30) PRIMARY KEY, ngay_tra DATE NOT NULL, trang_thai VARCHAR(20) NOT NULL CHECK(trang_thai IN ('PARTIAL','FULL')), INDEX ix_ngay_tra(ngay_tra), ly_do VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chi_tiet_tra_hang (ma_chi_tiet_tra VARCHAR(30) PRIMARY KEY, ma_tra_hang VARCHAR(30) NOT NULL, ma_chi_tiet VARCHAR(30) NOT NULL, so_luong_tra INT NOT NULL CHECK(so_luong_tra>0), tien_hoan DECIMAL(18,2) NOT NULL CHECK(tien_hoan>=0), FOREIGN KEY(ma_tra_hang) REFERENCES tra_hang(ma_tra_hang), FOREIGN KEY(ma_chi_tiet) REFERENCES chi_tiet_don_hang(ma_chi_tiet)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lich_su_cua_hang (ma_cua_hang VARCHAR(20) NOT NULL, ngay_hieu_luc DATE NOT NULL, khu_vuc_quan_ly VARCHAR(100) NOT NULL, PRIMARY KEY(ma_cua_hang,ngay_hieu_luc), FOREIGN KEY(ma_cua_hang) REFERENCES cua_hang(ma_cua_hang)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS raw_import_error (raw_id VARCHAR(40) PRIMARY KEY, loai_loi VARCHAR(50) NOT NULL, payload LONGTEXT NOT NULL CHECK(JSON_VALID(payload))) ENGINE=InnoDB;
